const FILE_TYPES = ['scorm', 'video', 'document', 'presentation'];
const config = $('Config').first().json;
const rows = $('When Called').all().map(i => i.json);
const response = $('Fetch DMS Folders').first().json || {};

/*  Only calls that upload files need a folder  */
const needsFolder = rows.some(r => FILE_TYPES.includes(String(r.resourceType || '').trim().toLowerCase()));
if (!needsFolder) {
  return [{ json: { needsCreate: false, noFilesInThisCall: true, dmsFolderGlobalId: '', targetPath: '' } }];
}

if (Array.isArray(response.errors) && response.errors.length) {
  throw new Error('Folder lookup failed: ' + JSON.stringify(response.errors));
}

const folderName = String((rows[0] || {}).dmsFolderName || '').trim();
if (!folderName) {
  throw new Error('dmsFolderName is required when any item has a file resource type (' + FILE_TYPES.join(', ') + ').');
}

const parentPath = String(config.DMS_PARENT_FOLDER_PATH || '').replace(/\/+$/, '');
const targetPath = parentPath + '/' + folderName;
const edges = (((response.data || {}).folders || {}).edges) || [];

/*  Two folders with the same name in the same parent would scatter files, so stop instead  */
if (edges.length > 1) {
  throw new Error('Found ' + edges.length + ' folders named "' + folderName + '" inside ' + parentPath + '. Remove the duplicate in Administrate and try again.');
}

const match = edges.length ? edges[0].node : null;
if (match && String(match.path || '') !== targetPath) {
  throw new Error('Matched a folder at "' + match.path + '" but expected "' + targetPath + '". Check that DMS_PARENT_FOLDER_ID and DMS_PARENT_FOLDER_PATH in Config point at the same folder.');
}

/*  Keep the base64 global ID: requestUpload rejects the numeric legacyId  */
return [{ json: {
  dmsFolderName: folderName,
  targetPath,
  needsCreate: !match,
  noFilesInThisCall: false,
  dmsFolderGlobalId: match ? String(match.id) : ''
} }];

const formatErrors = (response, fieldErrors) => {
  const messages = [];
  (response.errors || []).forEach(e => messages.push(e.message || JSON.stringify(e)));
  (fieldErrors || []).forEach(e => messages.push((e.label ? e.label + ': ' : '') + (e.message || JSON.stringify(e))));
  return messages;
};
/*  Reached when the folder already existed, was just created or is not needed.
    Normalises all three into the base64 global ID that requestUpload expects  */
const input = $input.first().json || {};
const createResult = ((input.data || {}).folders || {}).create || null;

if (input.data || input.errors) {
  const errors = formatErrors(input, (createResult || {}).errors);
  if (errors.length) {
    throw new Error('Could not create the DMS folder: ' + errors.join('; '));
  }
  const folder = (createResult || {}).folder || {};
  const newId = String(folder.id || '').trim();
  if (!newId) {
    throw new Error('The DMS folder was created but no ID came back, so there is nothing to file documents against.');
  }
  return [{ json: { dmsFolderGlobalId: newId, dmsFolderPath: String(folder.path || ''), folderWasCreated: true } }];
}

if (input.noFilesInThisCall === true) {
  return [{ json: { dmsFolderGlobalId: '', dmsFolderPath: '', folderWasCreated: false } }];
}

const globalId = String(input.dmsFolderGlobalId || '').trim();
if (!globalId) {
  throw new Error('No DMS folder was resolved for this call.');
}
return [{ json: { dmsFolderGlobalId: globalId, dmsFolderPath: String(input.targetPath || ''), folderWasCreated: false } }];

const FILE_TYPES = ['scorm', 'video', 'document', 'presentation'];
const rows = $('When Called').all().map(i => i.json);
const attachments = (($('List Sheet Attachments').first().json || {}).data) || [];

/*  Smartsheet pages attachments at 100 by default, so a short list would be a
    silent under-match rather than an error. Stop if we are on the boundary  */
if (attachments.length >= 100) {
  throw new Error('Smartsheet returned ' + attachments.length + ' attachments, which is at or over the default page size. Add includeAll=true to List Sheet Attachments before trusting this match.');
}

const byName = {};
const byRow = {};
attachments.forEach(a => {
  if (String(a.attachmentType || '') !== 'FILE') {
    return;
  }
  const name = String(a.name || '').trim().toLowerCase();
  if (name) {
    byName[name] = a;
  }
  if (String(a.parentType || '') === 'ROW' && a.parentId) {
    const key = String(a.parentId);
    if (!byRow[key]) {
      byRow[key] = a;
    }
  }
});

return rows.map(r => {
  const out = Object.assign({}, r);
  out.resourceType = String(r.resourceType || '').trim().toLowerCase();
  out.needsFile = FILE_TYPES.includes(out.resourceType);
  const rowId = String(r.smartsheetRowId || '').trim();
  const contentFile = String(r.contentFile || '').trim().toLowerCase();
  const byRowHit = rowId ? byRow[rowId] : null;
  const byNameHit = contentFile ? byName[contentFile] : null;
  const hit = byRowHit || byNameHit || null;
  if (hit) {
    out.attachmentId = hit.id;
    out.attachmentName = hit.name;
    out.attachmentMatchedBy = byRowHit ? 'row' : 'name';
  } else if (out.needsFile) {
    out.fileError = 'No Smartsheet attachment matched row "' + rowId + '" or file name "' + String(r.contentFile || '') + '".';
  }
  return { json: out };
});

const rows = $('Match Rows to Attachments').all().map(i => i.json);
const names = [];
rows.forEach(r => {
  String(r.tagsCsv || '').split(',').map(s => s.trim()).filter(Boolean).forEach(name => names.push(name));
});
const uniqueNames = [...new Set(names)];
if (!uniqueNames.length) {
  return [{ json: { tagName: '', noTags: true } }];
}
return uniqueNames.map(tagName => ({ json: { tagName } }));

/*  Lists the tags that do not exist yet. Always returns at least one item so
    exactly one branch of the next IF runs and Collect Tag Map runs once  */
const tagNames = $('Split Unique Tags').all().map(i => i.json.tagName);
const lookups = $('Find Tag').all().map(i => i.json);
const missing = tagNames.filter((tagName, index) => {
  const response = lookups[index] || {};
  if (Array.isArray(response.errors) && response.errors.length) {
    return false;
  }
  const edges = ((response.data || {}).learningTags || {}).edges || [];
  return edges.length === 0;
});
if (!missing.length) {
  return [{ json: { nothingToCreate: true } }];
}
return missing.map(tagName => ({ json: { tagName } }));

const formatErrors = (response, fieldErrors) => {
  const messages = [];
  (response.errors || []).forEach(e => messages.push(e.message || JSON.stringify(e)));
  (fieldErrors || []).forEach(e => messages.push((e.label ? e.label + ': ' : '') + (e.message || JSON.stringify(e))));
  return messages;
};
/*  Builds a tag name to ID map, then gives each row its learningTagIds.
    Runs before any content is created, so a tag failure stops the call cleanly  */
const tagIds = {};
const tagErrors = [];

if ($('Find Tag').isExecuted) {
  const tagNames = $('Split Unique Tags').all().map(i => i.json.tagName);
  const lookups = $('Find Tag').all().map(i => i.json);
  tagNames.forEach((tagName, index) => {
    const response = lookups[index] || {};
    const errors = formatErrors(response);
    if (errors.length) {
      tagErrors.push('Looking up tag "' + tagName + '" failed: ' + errors.join('; '));
      return;
    }
    const edges = ((response.data || {}).learningTags || {}).edges || [];
    if (edges.length) {
      tagIds[tagName.toLowerCase()] = edges[0].node.id;
    }
  });
}

if ($('Create Tag').isExecuted) {
  const toCreate = $('Find Missing Tags').all().map(i => i.json.tagName);
  const created = $('Create Tag').all().map(i => i.json);
  toCreate.forEach((tagName, index) => {
    const response = created[index] || {};
    const createResult = ((response.data || {}).learningTags || {}).create || {};
    const errors = formatErrors(response, createResult.errors);
    const tag = (createResult.learningTags || [])[0];
    if (errors.length || !tag || !tag.id) {
      tagErrors.push('Creating tag "' + tagName + '" failed: ' + (errors.join('; ') || 'no ID was returned'));
      return;
    }
    tagIds[tagName.toLowerCase()] = tag.id;
  });
}

if (tagErrors.length) {
  throw new Error('Learning Tags could not be resolved, so no content was created. ' + tagErrors.join(' | '));
}

const rows = $('Match Rows to Attachments').all().map(i => i.json);
return rows.map(r => {
  const names = String(r.tagsCsv || '').split(',').map(s => s.trim()).filter(Boolean);
  const ids = [...new Set(names.map(name => tagIds[name.toLowerCase()]).filter(Boolean))];
  return { json: Object.assign({}, r, { learningTagIds: ids }) };
});

const results = $input.all().map(i => i.json);
const failed = results.filter(r => !r.success);
const folder = $('Folder Ready').first().json;
return [{ json: {
  success: failed.length === 0,
  message: failed.length
    ? failed.length + ' of ' + results.length + ' content item(s) failed. See results.'
    : 'Created ' + results.length + ' content item(s).',
  createdCount: results.length - failed.length,
  failedCount: failed.length,
  dmsFolderId: folder.dmsFolderGlobalId,
  dmsFolderPath: folder.dmsFolderPath,
  folderWasCreated: folder.folderWasCreated,
  results
} }];

const row = $('Loop Content Rows').item.json;
const config = $('Config').first().json;
const attachment = $('Get Attachment URL').item.json || {};
const fileName = String(row.contentFile || row.attachmentName || 'content.zip');

/*  Resolved once per call, before the loop. This is the base64 global ID, not the
    legacyId. Blank omits the field and the file lands in the DMS root  */
const folderId = String($('Folder Ready').first().json.dmsFolderGlobalId || '').trim();

const input = {
  name: String(row.displayName || fileName),
  description: String(row.displayName || 'content'),
  contentType: String(attachment.mimeType || config.DEFAULT_CONTENT_TYPE),
  fileName
};
if (folderId) {
  input.folderId = folderId;
}
return { json: { query: 'mutation RequestDocumentUpload($input: DocumentUploadInput!) { documents { requestUpload(input: $input) { document { id name } uploadDetails { url payload } errors { label message value } } } }', variables: { input } } };

const formatErrors = (response, fieldErrors) => {
  const messages = [];
  (response.errors || []).forEach(e => messages.push(e.message || JSON.stringify(e)));
  (fieldErrors || []).forEach(e => messages.push((e.label ? e.label + ': ' : '') + (e.message || JSON.stringify(e))));
  return messages;
};
const requestUpload = (($json.data || {}).documents || {}).requestUpload || {};
const errors = formatErrors($json, requestUpload.errors);
if (!errors.length && !(requestUpload.document && requestUpload.uploadDetails)) {
  errors.push('no document or upload details were returned');
}
if (errors.length) {
  return { json: { uploadError: 'requestUpload failed: ' + errors.join('; ') } };
}
return $input.item;

const row = $('Loop Content Rows').item.json;
const toBoolean = value => value === true || ['true', 'yes'].includes(String(value).toLowerCase());
const isSet = value => value !== undefined && value !== null && value !== '';
const input = { eventId: String(row.eventId || ''), resourceType: row.resourceType };
if (row.displayName) {
  input.displayName = String(row.displayName);
}
if (isSet(row.ordering)) {
  input.ordering = Number(row.ordering);
}
if (isSet(row.isRequired)) {
  input.isRequired = toBoolean(row.isRequired);
}
if (isSet(row.autoComplete)) {
  input.autoComplete = toBoolean(row.autoComplete);
}
if (Array.isArray(row.learningTagIds) && row.learningTagIds.length) {
  input.learningTags = row.learningTagIds;
}
input.documentId = $('Request Upload').item.json.data.documents.requestUpload.document.id;
return { json: { query: 'mutation CreateLmsResource($input: CreateLmsResourceInput!) { event { createLmsResource(input: $input) { lmsContent { id } errors { label message value } } } }', variables: { input } } };

const row = $json;
const toBoolean = value => value === true || ['true', 'yes'].includes(String(value).toLowerCase());
const isSet = value => value !== undefined && value !== null && value !== '';
const input = { eventId: String(row.eventId || ''), resourceType: row.resourceType };
if (row.displayName) {
  input.displayName = String(row.displayName);
}
if (isSet(row.ordering)) {
  input.ordering = Number(row.ordering);
}
if (isSet(row.isRequired)) {
  input.isRequired = toBoolean(row.isRequired);
}
if (isSet(row.autoComplete)) {
  input.autoComplete = toBoolean(row.autoComplete);
}
if (Array.isArray(row.learningTagIds) && row.learningTagIds.length) {
  input.learningTags = row.learningTagIds;
}
if (row.resourceType === 'external' && row.externalActivityURL) {
  input.externalActivityURL = String(row.externalActivityURL);
}
return { json: { query: 'mutation CreateLmsResource($input: CreateLmsResourceInput!) { event { createLmsResource(input: $input) { lmsContent { id } errors { label message value } } } }', variables: { input } } };

const formatErrors = (response, fieldErrors) => {
  const messages = [];
  (response.errors || []).forEach(e => messages.push(e.message || JSON.stringify(e)));
  (fieldErrors || []).forEach(e => messages.push((e.label ? e.label + ': ' : '') + (e.message || JSON.stringify(e))));
  return messages;
};
/*  One result per content row. Reached after createLmsResource, or directly when
    the row's file was not found or the upload could not be requested  */
const row = $('Loop Content Rows').item.json;
const result = {
  eventId: row.eventId,
  displayName: row.displayName || '',
  resourceType: row.resourceType,
  ordering: row.ordering,
  success: false,
  lmsContentId: null,
  documentId: null,
  error: ''
};

if ($json.fileError) {
  result.error = $json.fileError;
} else if ($json.uploadError) {
  result.error = $json.uploadError;
} else {
  const createResult = (($json.data || {}).event || {}).createLmsResource || {};
  const errors = formatErrors($json, createResult.errors);
  if (!errors.length && !(createResult.lmsContent && createResult.lmsContent.id)) {
    errors.push('no LMS content ID was returned');
  }
  if (row.needsFile) {
    result.documentId = $('Build Resource Body (File)').item.json.variables.input.documentId;
  }
  if (errors.length) {
    result.error = 'createLmsResource failed: ' + errors.join('; ');
  } else {
    result.success = true;
    result.lmsContentId = createResult.lmsContent.id;
  }
}
return { json: result };
